import { autoAssetsConfig } from "../../autoAssetsConfig";

export const uiColors = { ink: "#263b32", cream: "#f4ebd5", dark: "#123e32", red: "#9b3541", gold: "#d5b878" };
export const uiFonts = autoAssetsConfig.fonts;

/** Стиль текста Classic XL, общий для компонентов и витрины. */
export function uiTextStyle(fontSize = 40, color = uiColors.ink): Phaser.Types.GameObjects.Text.TextStyle {
  return { fontFamily: uiFonts.interRegular.fontFamily, fontSize, color };
}
