import { openCommonModalInScene, UnSubManager, type ICommonModalSceneHandle } from "@kvisaz/phaser-common";
import { soundSettings } from "../../config.sound";
import { createDialogView } from "./DialogView";
import type { DialogKind, UiContext } from "./types";

/** Один диалог на экран. Дочерняя сцена приостанавливает карты и игровой таймер. */
export class Dialogs {
  private readonly unSubs = new UnSubManager();
  private dialog?: ICommonModalSceneHandle;

  /** Сохраняет контекст без подписок и без создания графических объектов. */
  constructor(private readonly context: UiContext) {
    // Активный диалог всегда закрывается вместе с экраном, даже если его не закрыли вручную.
    this.unSubs.addUnSub(() => { this.dialog?.destroy(); this.dialog = undefined; });
  }

  /** Открывает View через библиотечный lifecycle; действие выполняется после закрытия. */
  open(kind: DialogKind, onConfirm?: () => void, onCancel?: () => void) {
    if (this.dialog) return;
    let action: (() => void) | undefined;
    let closing = false;
    /** Повторный клик во время анимации не должен запускать действие дважды. */
    const close = (next?: () => void) => {
      if (closing) return;
      closing = true;
      action = next;
      this.dialog?.close();
    };
    this.dialog = openCommonModalInScene({
      parentScene: this.context.scene,
      createContent: (scene) => createDialogView({ ...this.context, scene }, {
        kind, settings: soundSettings,
        close: () => close(onCancel),
        dismiss: () => close(),
        confirm: () => close(onConfirm),
        onSettingsChange: (settings) => this.context.events.emit("coreSoundSettingsChanged", settings),
      }),
      props: { overlayAlpha: 0.55, overlayColor: "#000000", animationDuration: 180,
        isCloseOnOverlayClick: false,
        onClose: () => {
          this.dialog = undefined;
          this.context.events.emit("uiOut");
          // Действие после завершения дочерней сцены: без гонки resume/restart.
          this.context.scene.time.delayedCall(0, () => action?.());
        },
      },
    });
  }

  /** Удаляет активный диалог при уходе с экрана. */
  destroy() { this.unSubs.destroy(); }
}
