import type { SolitaireVariant } from "./types";
import { klondikeVariant } from "./klondike";
import { spiderVariant } from "./spider";
import { freecellVariant } from "./freecell";
import { yukonVariant } from "./yukon";
import { fortyThievesVariant } from "./fortyThieves";

/** Единственный список пяти пасьянсов: добавил игру — появилась в меню и витрине. */
export const variants = {
  klondike: klondikeVariant,
  spider: spiderVariant,
  freecell: freecellVariant,
  yukon: yukonVariant,
  fortyThieves: fortyThievesVariant,
} satisfies Record<string, SolitaireVariant>;

/** Id игры — ключ реестра. */
export type SolitaireId = keyof typeof variants;

/** Порядок кнопок меню и историй витрины. */
export const solitaireIds = Object.keys(variants) as SolitaireId[];
