import { makeView, makeAlign } from "@kvisaz/phaser-common";
import { imageAsset } from "../../assets";
import { iconButton, textButton } from "./buttons";
import { uiColors, uiFonts, uiTextStyle } from "./style";
import { toggle } from "./toggle";
import type { DialogProps, UiContext } from "./types";

/** Только View диалога Classic XL; открытием, паузой игры и затемнением занимается библиотека. */
export function createDialogView(context: UiContext, props: DialogProps) {
  const { scene, locale: { t } } = context;
  const { kind, close } = props;
  const closeButton = iconButton(context, "close", props.dismiss);
  const buttons = kind === "settings"
    ? [textButton(context, t("done"), close)]
    : [textButton(context, t(kind === "win" ? "back_to_menu" : "back_to_game"), close, "secondary", 500),
      textButton(context, t(kind === "home" ? "back_to_menu" : "new_game"), () => props.confirm?.(), "primary", 572)];
  const switches = kind === "settings" ? (["isSoundOn", "isMusicOn"] as const).map((key) =>
    toggle(context, props.settings[key], (value) => {
      props.settings[key] = value;
      props.onSettingsChange({ ...props.settings });
    })) : [];
  return makeView(scene, (b) => {
    const bg = b.nine({ ...imageAsset("windowBackground"), width: 1248, height: 740, padding: 16 });
    const header = b.rect({ width: 1244, height: 142, color: uiColors.dark });
    const title = b.text({ text: t(`dialog_${kind}`),
      style: { fontFamily: uiFonts.notoSerifBold.fontFamily, fontSize: 52, color: uiColors.cream } });
    const content: Phaser.GameObjects.GameObject[] = [];
    makeAlign((a) => {
      a.anchor(bg).centerX(header).topIn(header, 2);
      a.leftIn(title, 56).topIn(title, 37);
      a.rightIn(closeButton, -24).topIn(closeButton, 8);
      if (kind === "settings") {
        switches.forEach((button, i) => {
          const label = b.text({ text: t(i ? "music" : "sound"), style: uiTextStyle(48) });
          a.anchor(bg).leftIn(label, 80).topIn(label, 235 + i * 165);
          a.rightIn(button, -80).topIn(button, 200 + i * 165);
          content.push(label);
        });
      } else {
        const illustrated = kind === "win" || kind === "noMoves" || kind === "uselessMoves";
        const message = b.text({ text: t(`dialog_${kind}_message`),
          style: { ...uiTextStyle(40), wordWrap: { width: illustrated ? 650 : 1080 } } });
        a.anchor(bg).leftIn(message, 72).topIn(message, 240);
        content.push(message);
        if (illustrated) {
          const art = b.img(imageAsset(kind === "win" ? "dialogWin" : "dialogNoMoves")).setDisplaySize(300, 300);
          a.anchor(bg).rightIn(art, -64).topIn(art, 195);
          content.push(art);
        }
      }
      if (buttons.length === 1) a.anchor(bg).rightIn(buttons[0], -80).bottomIn(buttons[0], -72);
      else {
        a.anchor(bg).leftIn(buttons[0], 72).bottomIn(buttons[0], -72);
        a.rightIn(buttons[1], -72).bottomIn(buttons[1], -72);
      }
    });
    return b.con([bg, header, title, closeButton, ...content, ...switches, ...buttons]);
  });
}
