import type { IGameCoreSoundConfig } from "@kvisaz/phaser-common";
import type { ISolitairesEvents } from "./events";
import { autoAssetsConfig } from "./autoAssetsConfig";

/** Настройки звука текущего запуска: единственный источник истины меню, демо и диалогов. */
export interface ISoundSettings { isSoundOn: boolean; isMusicOn: boolean }

/** Текущие настройки; музыкальный трек пока отсутствует, поэтому isMusicOn выключен. */
export const soundSettings: ISoundSettings = { isSoundOn: true, isMusicOn: false };

/** Единые звуки пяти пасьянсов и UI; настройки и временный mute применяет gameCore. */
export const soundConfig: IGameCoreSoundConfig<ISolitairesEvents> = {
  initialSettings: { ...soundSettings },
  effects: {
    cardFlip: (scene) => {
      const key = autoAssetsConfig.sounds.hoverCardFlip.name;
      // Перенос и перевороты одного шага не должны накладывать одинаковые звуки.
      if (!scene.sound.isPlaying(key)) scene.sound.play(key);
    },
    cardDeal: (scene) => {
      const key = autoAssetsConfig.sounds.cardMultipleFlip.name;
      if (!scene.sound.isPlaying(key)) scene.sound.play(key);
    },
    cardReject: (scene) => {
      const key = autoAssetsConfig.sounds.cardSfx03.name;
      if (!scene.sound.isPlaying(key)) scene.sound.play(key, { volume: 0.5 });
    },
    solitaireWin: (scene) => scene.sound.play(autoAssetsConfig.sounds.fanfare.name, { volume: 0.5 }),
    uiClick: (scene) => scene.sound.play(autoAssetsConfig.sounds.click.name),
    uiHover: (scene) => scene.sound.play(autoAssetsConfig.sounds.hoverCardFlip.name),
    demoClick: (scene) => scene.sound.play(autoAssetsConfig.sounds.click.name),
    demoHover: (scene) => scene.sound.play(autoAssetsConfig.sounds.hoverCardFlip.name),
  },
};
