import { cardEngineV1, HtmlBackground, makeButton, SceneEvents, UnSubManager, type IClassicCardDto } from "@kvisaz/phaser-common";
import type { ISolitairesSceneEvents, SolitairesContext } from "../../events";
import type { OpenScreen, SolitaireId } from "../../screens";
import { autoAssetsConfig } from "../../autoAssetsConfig";
import { Dialogs } from "../ui/Dialogs";
import type { DialogKind } from "../ui/types";
import { SolitaireRound, type ISolitaireCoreState } from "./SolitaireRound";
import { SolitaireHud } from "./SolitaireHud";

/** Общие поля событий пяти партий: имена событий у каждой свои, с префиксом игры. */
interface ICoreEventData {
  source?: string;
  error?: unknown;
}

/** Тупик партии: ходов нет совсем или остались только перекладывания — подсказка их отбрасывает. */
function deadEnd({ hasMoves, hint }: ISolitaireCoreState): DialogKind | undefined {
  if (!hasMoves) return "noMoves";
  if (hint == null) return "uselessMoves";
}

/** Общий экран: связывает готовую партию библиотеки, UI и диалоги; сам не содержит правил. */
export class SolitaireView {
  private readonly unSubs = new UnSubManager();
  readonly round: SolitaireRound;

  /** Запускает выбранный пасьянс; заданная колода позволяет воспроизводить раздачу в сториз. */
  constructor(context: SolitairesContext, id: SolitaireId, open: OpenScreen, deck?: readonly IClassicCardDto[]) {
    const { scene, events } = context;
    const { EngineStep } = cardEngineV1;
    const background = new HtmlBackground({ url: autoAssetsConfig.images.backgroundCloth.url });
    const round = this.round = new SolitaireRound(context, id, deck);
    const { core, eventPrefix } = round;
    const dialogs = new Dialogs(context);
    const sceneEvents = new SceneEvents<ISolitairesSceneEvents>({ scene });
    const coreEvents = new SceneEvents<Record<string, ICoreEventData>>({ scene });
    let seconds = 0;
    /** Время стартует только после первого хода игрока: клика по карте, по колоде или перетаскивания. */
    let started = false;
    const hud = new SolitaireHud(context, id, round.config, sceneEvents);
    const timer = scene.time.addEvent({ delay: 1000, loop: true, callback: () => {
      const { won, historyLength } = core.state.getState();
      if (!started || won) return;
      hud.update(++seconds, historyLength);
    } });
    this.unSubs.addUnSub([
      () => sceneEvents.unSubscribeAll(), () => coreEvents.unSubscribeAll(), () => timer.remove(), dialogs, round, hud, background,
    ]);
    sceneEvents.on("hudHome", () => dialogs.open("home", () => open("menu")));
    sceneEvents.on("hudSettings", () => dialogs.open("settings"));
    sceneEvents.on("hudNewGame", () => dialogs.open("restart", () => open(id)));
    sceneEvents.on("hudUndo", () => { void core.undo(); });
    sceneEvents.on("hudMagic", () => { void core.magic(); });
    sceneEvents.on("hudHint", () => {
      const state = core.state.getState();
      const kind = state.step === EngineStep.IDLE ? deadEnd(state) : undefined;
      if (kind) dialogs.open(kind, () => open(id));
      else void core.showHint();
    });
    // Карты запаса ловит партия; пустое место колоды — клик игры: оборот сброса Косынки.
    if (round.stock) makeButton({ obj: round.stock, onClick: () => { started = true; void core.dealStock?.(); } });

    /** Звук — по фактам партии: одно событие — один звук. */
    coreEvents.on(`${eventPrefix}CardDealt`, () => events.emit("cardDeal"));
    coreEvents.on(`${eventPrefix}MoveStarted`, ({ source }) => {
      started = true;
      events.emit(source === "stock" ? "cardDeal" : "cardFlip");
    });
    coreEvents.on(`${eventPrefix}InvalidMove`, () => {
      started = true;
      events.emit("cardReject");
    });
    coreEvents.on(`${eventPrefix}Error`, ({ error }) => console.error("Solitaire:", error));

    this.unSubs.addUnSub(core.state.on((state) => {
      // Перетаскивание — тоже первый ход: таймер стартует сразу, не дожидаясь дропа.
      if (state.step === EngineStep.DRAGGING) started = true;
      // enabled — только смысловые условия: транзиентный step не мигает кнопками.
      // Повторный запуск во время анимации гасит партия: её действия работают только в IDLE.
      hud.undo.setData("enabled", state.historyLength > 0);
      hud.hint.setData("enabled", !state.won);
      // Тинт палочки — по готовому ходу магии в состоянии партии.
      hud.magic?.setData("enabled", state.magic != null);
      hud.update(seconds, state.historyLength);
    }));
    this.unSubs.addUnSub(core.state.on(({ action }) => {
      if (action === "undo") events.emit("cardFlip");
    }, "action"));
    this.unSubs.addUnSub(core.state.on(({ won }) => {
      if (!won) return;
      events.emit("solitaireWin");
      dialogs.open("win", () => open(id), () => open("menu"));
    }, "won"));
    // Тупик сообщаем сам, только когда он появился: перекладывания не открывают диалог после каждого хода.
    let lastDeadEnd: DialogKind | undefined;
    this.unSubs.addUnSub(core.state.on((state) => {
      if (state.step !== EngineStep.IDLE || state.won) return;
      const kind = deadEnd(state);
      if (kind && kind !== lastDeadEnd) dialogs.open(kind, () => open(id));
      lastDeadEnd = kind;
    }));
    // start() сразу публикует состояние раздачи — подписка выше сама выставит кнопки.
    core.start();
  }

  /** Отписывает UI, останавливает партию и удаляет все объекты экрана. */
  destroy(): void {
    this.unSubs.destroy();
  }
}
