import { makeView, SwitchButton } from "@kvisaz/phaser-common";
import { imageAsset } from "../../assets";
import type { UiContext } from "./types";

/** Переключатель 256×128 без подписи: готовые PNG и состояние библиотечного SwitchButton. */
export function toggle(context: UiContext, isOn: boolean, onChange: (value: boolean) => void) {
  const viewOn = makeView(context.scene, (b) => b.img(imageAsset("toggleOn")));
  const viewOff = makeView(context.scene, (b) => b.img(imageAsset("toggleOff")));
  return new SwitchButton({
    viewOn, viewOff, isOn,
    onSwitchClick: (value) => { context.events.emit("uiClick"); onChange(value); },
    onOver: () => context.events.emit("uiHover"),
    onOut: () => context.events.emit("uiOut"),
  });
}
