import type { ImageFrameData } from "@kvisaz/phaser-common";
import { autoAssetsConfig } from "./autoAssetsConfig";

/** Имя картинки из автосборки ассетов; используется конфигами и UI. */
export type ImageAssetKey = keyof typeof autoAssetsConfig.images;

/** Приводит отдельную картинку или кадр атласа к формату makeView. */
export function imageAsset(key: ImageAssetKey): ImageFrameData {
  const asset = autoAssetsConfig.images[key];
  return "frameName" in asset
    ? { textureName: asset.url, frameName: asset.frameName }
    : { textureName: asset.name };
}
