import { cardEngineV1, createSimpleCardData, makeView, makeAlign, UnSubManager,
  type ICardPlace, type IClassicCardDto, type Observable } from "@kvisaz/phaser-common";
import type { SolitairesContext } from "../../events";
import { layoutPlaces } from "../solitaires/layoutPlaces";
import { placeView, stackLayout, tableLayout } from "../solitaires/tableLayout";
import type { SolitaireId } from "../../screens";
import { CardView, CARD_HEIGHT, CARD_WIDTH } from "../shared/CardView/CardView";
import { variants } from "../solitaires/variants";
import { uiTextStyle } from "../ui/style";
import type { ISolitaireConfig } from "../solitaires/types";

/** Общее состояние пяти готовых партий библиотеки: экран читает только эти поля. */
export interface ISolitaireCoreState {
  readonly step: cardEngineV1.EngineStep;
  readonly action?: string;
  readonly historyLength: number;
  /** Подсказка — лучший полезный ход; её может не быть и при ходах. */
  readonly hint?: unknown;
  /** Ход по правилам есть, включая запас; нет — «Ходов нет». */
  readonly hasMoves: boolean;
  /** Нет магии — кнопка палочки тускнеет. */
  readonly magic?: unknown;
  readonly won: boolean;
}

/** Общее у пяти готовых партий: KlondikeCoreGame, SpiderCoreGame и остальные подходят без обёрток. */
export interface ISolitaireCore {
  readonly state: Observable<Readonly<ISolitaireCoreState>>;
  start(): void;
  undo(): Promise<void>;
  showHint(): Promise<void>;
  magic(): Promise<void>;
  /** Запас: есть у Косынки, Паука и 40 разбойников. */
  dealStock?(): Promise<void>;
  destroy(): void;
}

/** Одна партия: плоское поле и готовая партия библиотеки, никаких корневых контейнеров. */
export class SolitaireRound {
  private readonly unSubs = new UnSubManager();
  readonly config: ISolitaireConfig;
  readonly core: ISolitaireCore;
  /** Префикс событий партии для SceneEvents экрана. */
  readonly eventPrefix: string;
  readonly cards: CardView[];
  readonly stock?: ICardPlace;

  /** Раскладывает места и передаёт их готовой партии выбранной игры; раздачу запускает экран через core.start(). */
  constructor(context: SolitairesContext, readonly id: SolitaireId, deck?: readonly IClassicCardDto[]) {
    const { scene, locale: { t } } = context;
    const spec = variants[id];
    this.config = spec.config;
    const { config } = this;
    const scale = config.cardScale;
    this.cards = (deck ?? createSimpleCardData({ copies: config.deckCopies, suits: config.deckSuits })).map((dto, i) =>
      new CardView({ scene, t, ...dto, id: `card-${i}` }).setScale(scale));
    // Сначала останавливаем анимации и ввод партии, только затем удаляем места. Карты уничтожает партия.
    this.unSubs.addUnSub(() => this.core.destroy());
    /** Место имеет те же полные границы, что PNG карты, включая прозрачный край тени. */
    const place = (type: string) => {
      const view = placeView({ scene, type, width: CARD_WIDTH * scale, height: CARD_HEIGHT * scale });
      this.unSubs.addUnSub(view);
      return view;
    };
    const stock = this.stock = config.stockMode !== "none" ? place("stock") : undefined;
    const waste = config.stockMode === "once" || config.stockMode === "recycle" ? place("waste") : undefined;
    const cells = Array.from({ length: config.cellCount }, () => place("cell"));
    const bases = Array.from({ length: config.baseCount }, () => place("base"));
    const tables = Array.from({ length: config.tableColumns }, () => place("table"));
    const upper = [...(stock ? [stock] : []), ...(waste ? [waste] : []), ...cells, ...bases];
    layoutPlaces(scene, config, tables, upper, stock, waste);
    // Базы отличаются от свободных ячеек, но не закреплены за конкретной мастью.
    bases.forEach((base) => {
      const label = makeView(scene, (b) => b.text({ text: t(config.baseStartValue === "king" ? "rank_king" : "rank_ace"),
        style: uiTextStyle(config.baseLabelSize * scale, "#739583") })).setDepth(-1);
      makeAlign((a) => a.anchor(base).center(label));
      this.unSubs.addUnSub(label);
    });

    /** Роли мест для партии: колонки — адаптивная раскладка игры, остальное — плотная стопка. */
    const table = tableLayout(config, scene.scale.height - config.tableBottomMargin);
    const tablePlaces = tables.map((cardPlace) => ({ cardPlace, layout: table }));
    const stack = (cardPlace: ICardPlace) => ({ cardPlace, layout: stackLayout });
    /** Юкону и FreeCell колода нужна только для раздачи: невидимая зона на месте первой колонки, как раньше. */
    const startDeal = () => {
      const zone = scene.add.zone(0, 0, CARD_WIDTH * scale, CARD_HEIGHT * scale);
      makeAlign((a) => a.anchor(tables[0]).center(zone));
      this.unSubs.addUnSub(zone);
      return stack(zone);
    };
    const props = { scene, cards: this.cards,
      timings: { moveDurationMs: config.moveDuration, flipDurationMs: config.flipDuration } };
    const { KlondikeCoreGame, SpiderCoreGame, FreeCellCoreGame, YukonCoreGame, FortyThievesCoreGame } = cardEngineV1;
    /** Одна запись на игру: префикс её событий и создание партии. Забытая игра — ошибка типа.
     * Партия создаётся лениво, поэтому колода и сброс читаются только там, где они есть. */
    const cores = {
      klondike: { prefix: "klondike", create: () => new KlondikeCoreGame({ ...props,
        cardPlaces: { deck: stack(stock!), deckGrave: stack(waste!), tables: tablePlaces, bases: bases.map(stack) } }) },
      spider: { prefix: "spider", create: () => new SpiderCoreGame({ ...props,
        cardPlaces: { deck: stack(stock!), tables: tablePlaces, bases: bases.map(stack) } }) },
      freecell: { prefix: "freeCell", create: () => new FreeCellCoreGame({ ...props,
        cardPlaces: { tables: tablePlaces, cells: cells.map(stack), bases: bases.map(stack), startDeal: startDeal() } }) },
      yukon: { prefix: "yukon", create: () => new YukonCoreGame({ ...props,
        cardPlaces: { tables: tablePlaces, bases: bases.map(stack), startDeal: startDeal() } }) },
      fortyThieves: { prefix: "fortyThieves", create: () => new FortyThievesCoreGame({ ...props,
        cardPlaces: { deck: stack(stock!), deckGrave: stack(waste!), tables: tablePlaces, bases: bases.map(stack) } }) },
    } satisfies Record<SolitaireId, { prefix: string; create: () => ISolitaireCore }>;
    this.eventPrefix = cores[id].prefix;
    this.core = cores[id].create();
  }

  /** Отменяет жесты/твины перед удалением карт и мест. */
  destroy() { this.unSubs.destroy(); }
}
