import { adaptiveHiddenOpenTailCardLayoutStrategy, fromTopCardLayoutStrategy, makeView,
  type ICardPlace, type IClassicAbstractCard, type ILayoutStrategy } from "@kvisaz/phaser-common";
import { alternating, descending } from "./rules";
import type { ISolitaireConfig } from "./types";

/** Запас, сброс, ячейки и базы — плотная стопка, как в сторях движка. */
export const stackLayout: ILayoutStrategy = (items, zone) => fromTopCardLayoutStrategy(items, zone, { cardOffset: 0, marginTop: 0 });

interface IPlaceViewProps {
  scene: Phaser.Scene;
  /** base — тёмное место базы, остальные — обычные. */
  type: string;
  width: number;
  height: number;
}

/** Прямоугольник места под карту, под картами по глубине. */
export function placeView({ scene, type, width, height }: IPlaceViewProps): ICardPlace {
  return makeView(scene, (b) => b.rect({ width, height,
    color: type === "base" ? "#103a2c" : "#174737", strokeColor: "#739583", strokeWidth: 1 })).setDepth(-1);
}

/** Общая адаптивная раскладка: длина переносимого хвоста зависит от режима игры. */
export function tableLayout(config: ISolitaireConfig, bottomBoundaryY: number): ILayoutStrategy {
  return (items, target) => {
    const cards = items as IClassicAbstractCard[];
    let tailStartIndex = cards.length;
    // Хвост считаем только от открытой верхней карты; «single» означает ровно одну карту.
    if (cards.at(-1)?.isFaceUp) {
      tailStartIndex--;
      while (tailStartIndex > 0 && config.tailMode !== "single") {
        const prev = cards[tailStartIndex - 1], card = cards[tailStartIndex];
        if (!prev.isFaceUp) break;
        const linked = config.tailMode === "sameSuit" ? prev.suit === card.suit && descending(prev, card)
          : config.tailMode === "anyFace" ? true : alternating(prev, card);
        if (!linked) break;
        tailStartIndex--;
      }
    }
    adaptiveHiddenOpenTailCardLayoutStrategy(items, target, {
      tailStartIndex, marginTop: config.marginTop, bottomBoundaryY,
      hiddenOffsetY: config.hiddenOffsetY, maxHiddenOffsetCards: config.maxHiddenOffsetCards,
      minVisibleOffsetY: config.minVisibleOffsetY, maxVisibleOffsetY: config.maxVisibleOffsetY,
      minTailOffsetY: config.minTailOffsetY, maxTailOffsetY: config.maxTailOffsetY,
    });
  };
}
