import { HtmlBackground, makeButton, makeView, UnSubManager, arrayAlign, makeAlign } from "@kvisaz/phaser-common";
import { autoAssetsConfig } from "../../autoAssetsConfig";
import { imageAsset } from "../../assets";
import type { SolitairesContext } from "../../events";
import { solitaireIds, type OpenScreen } from "../../screens";
import { variants } from "../solitaires/variants";
import { screenButton } from "../ui/screenUi";
import { iconButton } from "../ui/buttons";
import { uiColors, uiFonts } from "../ui/style";
import { Dialogs } from "../ui/Dialogs";

const layout = { buttonWidth: 680, buttonHeight: 98, buttonGap: 18, slice: 16 };

/** Стартовый экран: пять игр и отдельный стенд проверки стартера. */
export class MenuView {
  private readonly unSubs = new UnSubManager();

  /** Собирает Classic XL из PNG и текста; интерактивность подключает makeButton. */
  constructor(context: SolitairesContext, open: OpenScreen) {
    const {
      scene,
      events,
      locale: { t },
    } = context;
    this.unSubs.addUnSub(
      new HtmlBackground({ url: autoAssetsConfig.images.backgroundCloth.url }),
    );
    const buttons = solitaireIds.map((id) => {
      const button = makeView(scene, (b) => {
        const bg = b.nine({
          ...imageAsset("buttonDefault"),
          width: layout.buttonWidth,
          height: layout.buttonHeight,
          padding: layout.slice,
        });
        const icon = b.img(imageAsset(variants[id].config.menuIcon)).setDisplaySize(32, 35);
        const label = b.text({
          text: t(id),
          style: {
            fontFamily: uiFonts.interSemibold.fontFamily,
            fontSize: "38px",
            color: uiColors.ink,
          },
        });
        makeAlign((a) => {
          a.anchor(bg).leftIn(icon, 28).centerY(icon);
          a.leftIn(label, 86).centerY(label);
        });
        return b.con([bg, icon, label]);
      });
      makeButton({
        obj: button,
        onClick: () => {
          events.emit("uiClick");
          open(id);
        },
        onHover: () => events.emit("uiHover"),
        onOut: () => events.emit("uiOut"),
      });
      return button;
    });
    const demo = screenButton(context, t("demo_title"), () => open("demo"));
    const dialogs = new Dialogs(context);
    const settings = iconButton(context, "settings", () => dialogs.open("settings"));
    this.unSubs.addUnSub([dialogs, settings, demo, ...buttons]);
    makeView(scene, (b) => {
      const hero = b.img(imageAsset("hero02")).setDisplaySize(660, 660);
      const title = b.text({
        text: t("title"),
        style: { fontFamily: uiFonts.notoSerifBold.fontFamily, fontSize: "88px", color: uiColors.cream },
      });
      const subtitle = b.text({
        text: t("menu_subtitle"),
        style: { fontFamily: uiFonts.interRegular.fontFamily, fontSize: "32px", color: "#d6e1cf" },
      });
      makeAlign((a) => a.column(buttons, layout.buttonGap));
      const choices = arrayAlign.alignObject(buttons);
      makeAlign((a) => {
        a.anchorSceneScreen(scene);
        a.leftIn(title, 120).topIn(title, 146);
        a.leftIn(subtitle, 126).topIn(subtitle, 279);
        a.leftIn(hero, 116).topIn(hero, 344);
        a.rightIn(choices, -130).topIn(choices, 240);
        a.rightIn(settings, -48).topIn(settings, 12);
        a.anchor(choices).centerX(demo).bottomTo(demo, 48);
      });
      this.unSubs.addUnSub([hero, title, subtitle]);
      return hero;
    });
  }

  /** Удаляет меню при завершении Host-сцены. */
  destroy(): void {
    this.unSubs.destroy();
  }
}
