import { fitToSize, makeButton, makeView, makeAlign } from "@kvisaz/phaser-common";
import { imageAsset } from "../../assets";
import type { UiContext } from "./types";
import { uiColors, uiFonts } from "./style";

export const iconAssets = {
  home: "iconHome", undo: "iconUndo", hint: "iconHint", newGame: "iconNewGame",
  magic: "iconMagicCard", settings: "iconSettings", close: "iconClose",
} as const;
export type IconName = keyof typeof iconAssets;

/**
 * Все кнопки — Image/Container через makeView и makeButton: клик, hover и disabled
 * приходят из библиотеки, своих обработчиков указателя нет.
 * Disabled-вид — мягкий tint, как в game_202601_pauk_01 (ViewElementBuilder.imageButton),
 * чтобы кнопка не мигала прозрачностью при смене enabled во время хода.
 */
export function iconButton(context: UiContext, name: IconName, onClick: () => void, size = 128) {
  const image = makeView(context.scene, (b) => b.img(imageAsset(iconAssets[name])));
  fitToSize({ gameObject: image, width: size, height: size });
  return makeButton({
    obj: image,
    onClick: () => { context.events.emit("uiClick"); onClick(); },
    onHover: () => context.events.emit("uiHover"),
    onOut: () => context.events.emit("uiOut"),
    onEnabledChange: (obj, enabled) => enabled ? obj.clearTint() : obj.setTint(0xdedede),
  }).setName(name);
}

/** Текстовая кнопка с одним из трёх NineSlice-фонов дизайна. */
export function textButton(context: UiContext, text: string, onClick: () => void,
  variant: "default" | "primary" | "secondary" = "primary", width = 520) {
  const assets = { default: "buttonDefault", primary: "buttonPrimary", secondary: "buttonSecondary" } as const;
  const button = makeView(context.scene, (b) => {
    const bg = b.nine({ ...imageAsset(assets[variant]), width, height: 112, padding: 16 });
    const label = b.text({ text, style: { fontFamily: uiFonts.interSemibold.fontFamily, fontSize: 40,
      color: variant === "primary" ? uiColors.cream : uiColors.ink } });
    makeAlign((a) => a.anchor(bg).center(label));
    return b.con([bg, label]);
  });
  return makeButton({
    obj: button,
    onClick: () => { context.events.emit("uiClick"); onClick(); },
    onHover: () => context.events.emit("uiHover"),
    onOut: () => context.events.emit("uiOut"),
  });
}
