import { CardView as CoreCardView, CardSuit, scaleToSize, isSuitRed, makeAlign, makeView,
  type CardSide, type CardValue } from "@kvisaz/phaser-common";
import { imageAsset } from "../../../assets";
import { uiColors, uiFonts } from "../../ui/style";
import type { SolitairesContext } from "../../../events";

export const CARD_WIDTH = 154;
export const CARD_HEIGHT = 210;
export const suitAssets = {
  [CardSuit.spade]: "suitSpade", [CardSuit.heart]: "suitHeart",
  [CardSuit.club]: "suitClub", [CardSuit.diamond]: "suitDiamond",
} as const;
const figureNames = { jack: "Jack", queen: "Queen", king: "King", ace: "Ace" } as const;
const suitNames = {
  [CardSuit.spade]: "Spade", [CardSuit.heart]: "Heart",
  [CardSuit.club]: "Club", [CardSuit.diamond]: "Diamond",
} as const;

export interface CardProps {
  scene: Phaser.Scene; id: string; suit: CardSuit; value: CardValue; side?: CardSide;
  t: SolitairesContext["locale"]["t"];
}

/** Карта Classic XL на библиотечном контракте: id, suit, value, side, flip и stackId. */
export class CardView extends CoreCardView {
  readonly id: string;
  readonly suit: CardSuit;
  readonly value: CardValue;

  /** Собирает лицо с мастью или фигурой J/Q/K/A; контракт карты и рубашка не меняются. */
  constructor({ scene, t, id, suit, value, side = "back" }: CardProps) {
    const face = makeView(scene, (b) => {
      const bg = b.img(imageAsset("cardFace"));
      const style = { fontFamily: uiFonts.notoSerifBold.fontFamily, fontSize: 27,
        color: isSuitRed(suit) ? uiColors.red : uiColors.ink };
      const label = typeof value === "string" ? t(`rank_${value}`) : String(value);
      const upper = b.text({ text: label, style });
      const lower = b.text({ text: label, style });
      const small = b.img(imageAsset(suitAssets[suit])).setDisplaySize(22, 24);
      const figure = typeof value === "string";
      const center = b.img(imageAsset(figure
        ? `card${figureNames[value]}${suitNames[suit]}`
        : suitAssets[suit]));
      // Целевая область не зависит от разрешения PNG; пропорции сохраняются.
      scaleToSize({ gameObject: center, width: figure ? 117 : 60, height: figure ? 130 : 65 });
      makeAlign((a) => {
        a.anchor(bg).leftIn(upper, 16).topIn(upper, 7);
        a.rightIn(lower, -16).bottomIn(lower, -10);
        a.anchor(upper).rightTo(small, 5).centerY(small);
        a.anchor(bg).center(center);
      });
      return b.con([bg, upper, lower, small, center]);
    });
    const back = makeView(scene, (b) => b.img(imageAsset("cardBack")));
    super({ scene, faceImage: face, backImage: back, initSide: side, initStackId: "deck" });
    this.id = id;
    this.suit = suit;
    this.value = value;
  }
}
