import { isSuitRed, type CardValue, type IClassicAbstractCard } from "@kvisaz/phaser-common";

export const ranks: readonly CardValue[] = ["ace", 2, 3, 4, 5, 6, 7, 8, 9, 10, "jack", "queen", "king"];
/** Номинал от младшего туза до короля. */
export const rank = (card: IClassicAbstractCard) => ranks.indexOf(card.value);
/** Убывание на один номинал. */
export const descending = (lower: IClassicAbstractCard, upper: IClassicAbstractCard) => rank(lower) === rank(upper) + 1;
/** Убывание с чередованием красного и чёрного. */
export const alternating = (lower: IClassicAbstractCard, upper: IClassicAbstractCard) =>
  descending(lower, upper) && isSuitRed(lower.suit) !== isSuitRed(upper.suit);
