import type { ICardPlace } from "@kvisaz/phaser-common";
import { arrayAlign, makeAlign } from "@kvisaz/phaser-common";
import type { ISolitaireConfig } from "./types";

/** Совмещает края колоды и баз с краями стола; при нехватке ширины раздвигает колонки. */
export function layoutPlaces(scene: Phaser.Scene, config: ISolitaireConfig, tables: ICardPlace[],
  upper: ICardPlace[], stock?: ICardPlace, waste?: ICardPlace) {
  const narrow = config.tableColumns === config.narrowTableColumns;
  const gap = narrow ? config.narrowUpperGap : config.wideUpperGap;
  const tableGap = narrow ? config.narrowTableGap : config.wideTableGap;
  makeAlign((a) => {
    a.row(upper, gap);
    const requiredWidth = arrayAlign.alignObject(upper).getBounds().width + (stock ? gap : 0);
    const cardsWidth = tables.reduce((sum, p) => sum + p.getBounds().width, 0);
    a.row(tables, stock ? Math.max(tableGap, (requiredWidth - cardsWidth) / (tables.length - 1)) : tableGap);
    const tableBounds = arrayAlign.alignObject(tables);
    a.anchorSceneScreen(scene).centerX(tableBounds, config.centerXOffset).topIn(tableBounds, config.tableTopY);
    if (config.alignUpperRowToColumns) {
      const actualGap = tables[1].getBounds().left - tables[0].getBounds().right;
      a.row(upper.filter((p) => p !== stock && p !== waste), actualGap);
      if (config.deckWasteSameGap && stock && waste) a.row([stock, waste], actualGap);
    }
    const upperBounds = arrayAlign.alignObject(upper);
    a.anchorSceneScreen(scene).centerX(upperBounds, config.centerXOffset).topIn(upperBounds, config.upperTopY);
    if (stock) {
      const deck = arrayAlign.alignObject(waste ? [stock, waste] : [stock]);
      const bases = arrayAlign.alignObject(upper.filter((p) => p !== stock && p !== waste));
      a.anchor(tableBounds).leftIn(deck).rightIn(bases);
    }
  });
}
