import packageInfo from "../package.json";
import { GameEventBus, runGameCore } from "@kvisaz/phaser-common";
import { phaserGameConfig } from "./config";
import { localeConfig } from "./config.locale";
import { soundConfig } from "./config.sound";
import { autoAssetsConfig } from "./autoAssetsConfig";
import type { ISolitairesConfig, ISolitairesEvents, ISolitairesSave } from "./events";
import { createScreenFactory, type StartGameOptions } from "./createScreenFactory";

/** Один раз запускает ядро; экран меняется перезапуском его Host-сцены. */
export function startGame(options: StartGameOptions = {}) {
  return runGameCore<ISolitairesEvents, ISolitairesConfig, ISolitairesSave>({
    config: {
      app: { id: packageInfo.name, parentId: "game" },
      phaser: phaserGameConfig,
      preload: { loaderElementId: "loader" },
      platform: { enabled: false },
      storage: { dataKey: `${packageInfo.name}-state` },
      ads: {
        cooldownMs: 500,
        isMock: true,
        fullscreenAdFlows: [
          { requestEvent: "demoFullscreenRequest", continueEvent: "demoFullscreenContinue" },
        ],
      },
      sound: soundConfig,
      cursor: {
        events: {
          demoHover: () => "pointer",
          demoOut: () => "auto",
          uiHover: () => "pointer",
          uiOut: () => "auto",
        },
        styles: { pointer: "pointer", auto: "auto" },
        initialType: "auto",
        resetStyle: "auto",
      },
      locale: localeConfig,
      browser: { disableContextMenu: true, iosAudioResumePatch: true },
    },
    assets: {
      ...autoAssetsConfig.preload,
      // Фоны с префиксом background загружает HtmlBackground, не Phaser.
      images: autoAssetsConfig.preload.images.filter(({ name }) => !name.startsWith("background")),
    },
    events: new GameEventBus<ISolitairesEvents>(),
    gameConfig: { incrementStep: 1 },
    createGameContent: createScreenFactory(options),
  });
}
