import { makeView, UnSubManager, arrayAlign, makeAlign, type SceneEvents } from "@kvisaz/phaser-common";
import type { ISolitairesSceneEvents } from "../../events";
import type { SolitaireId } from "../../screens";
import type { ISolitaireConfig } from "../solitaires/types";
import { iconButton } from "../ui/buttons";
import type { UiContext } from "../ui/types";
import { uiColors, uiFonts, uiTextStyle } from "../ui/style";

/** Общая панель пяти игр: название, время, ходы и кнопки из Classic XL. */
export class SolitaireHud {
  private readonly unSubs = new UnSubManager();
  private readonly stats: Phaser.GameObjects.Text;
  readonly undo: Phaser.GameObjects.Image;
  readonly hint: Phaser.GameObjects.Image;
  readonly newGame: Phaser.GameObjects.Image;
  /** Кнопки нет, если игра не включает магическую палочку в своём конфиге. */
  readonly magic?: Phaser.GameObjects.Image;

  /**
   * Создаёт UI непосредственно в сцене, без родительского контейнера.
   * Кнопки не знают про экран: они эмитят команды `hud*` в SceneEvents, а обработку ведёт SolitaireView.
   */
  constructor(private readonly context: UiContext, id: SolitaireId, config: ISolitaireConfig,
    sceneEvents: SceneEvents<ISolitairesSceneEvents>) {
    const { scene, locale: { t } } = context;
    const bg = makeView(scene, (b) => b.rect({ width: 1920, height: 152, color: uiColors.dark }));
    const title = makeView(scene, (b) => b.text({ text: t(id),
      style: { fontFamily: uiFonts.notoSerifBold.fontFamily, fontSize: 48, color: uiColors.cream } }));
    const home = iconButton(context, "home", () => sceneEvents.emit("hudHome"));
    const settings = iconButton(context, "settings", () => sceneEvents.emit("hudSettings"));
    this.newGame = iconButton(context, "newGame", () => sceneEvents.emit("hudNewGame"));
    this.undo = iconButton(context, "undo", () => sceneEvents.emit("hudUndo"));
    this.hint = iconButton(context, "hint", () => sceneEvents.emit("hudHint"));
    this.magic = config.magicWandEnabled ? iconButton(context, "magic", () => sceneEvents.emit("hudMagic")) : undefined;
    // Правый край статистики закреплён у настроек: текст растёт влево и не наезжает на кнопку.
    this.stats = makeView(scene, (b) => b.text({ text: "", style: uiTextStyle(30, uiColors.cream) })).setOrigin(1, 0.5);
    this.update(0, 0);
    const controls = [this.newGame, this.undo, this.hint, ...(this.magic ? [this.magic] : [])];
    makeAlign((a) => {
      a.anchorSceneScreen(scene).leftIn(bg).topIn(bg);
      a.leftIn(home, 32).topIn(home, 12);
      a.rightIn(settings, -48).topIn(settings, 12);
      a.leftIn(title, 220).topIn(title, 38);
      a.column(controls, config.layoutLeftBarGapPx);
      a.anchorSceneScreen(scene).leftIn(arrayAlign.alignObject(controls), config.layoutLeftBarLeftPx)
        .topIn(arrayAlign.alignObject(controls), config.layoutLeftBarTopPx);
      a.anchor(settings).leftTo(this.stats, -32).centerY(this.stats);
    });
    this.unSubs.addUnSub([bg, title, home, settings, this.stats, ...controls]);
  }

  /** Показывает фактические ходы движка и время активной сцены. */
  update(seconds: number, moves: number) {
    const { t } = this.context.locale;
    const time = `${Math.floor(seconds / 60).toString().padStart(2, "0")}:${(seconds % 60).toString().padStart(2, "0")}`;
    this.stats.setText(`${t("time")}  ${time}     ·     ${t("moves")}  ${moves}`);
  }

  /** Удаляет все элементы панели. */
  destroy() { this.unSubs.destroy(); }
}
