import { makeButton, makeView, makeAlign } from "@kvisaz/phaser-common";
import type { SolitairesContext } from "../../events";
import { uiColors, uiTextStyle } from "./style";

/** Общая кнопка экранов (меню, стенд); звук, hover и курсор обслуживает GameCore. */
export function screenButton(context: SolitairesContext, text: string, run: () => void) {
  const { scene, events } = context;
  const button = makeView(scene, (b) => {
    const bg = b.rect({ width: 270, height: 64, color: uiColors.gold });
    const label = b.text({ text, style: uiTextStyle(26, uiColors.ink) });
    makeAlign((a) => a.anchor(bg).center(label));
    return b.con([bg, label]);
  });
  return makeButton({
    obj: button,
    onClick: () => {
      events.emit("uiClick");
      run();
    },
    onHover: () => events.emit("uiHover"),
    onOut: () => events.emit("uiOut"),
  });
}
